using System.Diagnostics;
using System.Text.Json;
var commit = Arg("--commit") ?? throw new ArgumentException("--commit required"); var size = int.Parse(Arg("--size") ?? "1000000"); var seed = int.Parse(Arg("--seed") ?? "1209"); var runs = int.Parse(Arg("--runs") ?? "10"); var random = new Random(seed); var data = Enumerable.Range(0, size).Select(i => (Category: $"category-{random.Next(100)}", Amount: (decimal)random.NextDouble() * 1000)).ToArray(); long Run() { var sw = Stopwatch.StartNew(); _ = data.GroupBy(x => x.Category).Select(g => (g.Key, Total: g.Sum(x => x.Amount))).OrderByDescending(x => x.Total).ToArray(); return sw.ElapsedMilliseconds; }
